'use strict';
const GUEST_KEY='lemonade-empire-save-v1';
const clientId=crypto.randomUUID();
const accountChannel=typeof BroadcastChannel==='function'?new BroadcastChannel('lemonade-empire-accounts'):null;
let player=null,revision=0,dirty=false,cloudTimer=0,inFlight=null,signupMode=false,authBusy=false,epoch=0,ackResolver=null;
function status(message){window.cloudSaveMessage=message;$('cloud-status').textContent=message;if(player)$('profile-save').textContent=message;}
function pauseGame(paused){window.cloudPaused=paused;document.querySelector('main').inert=paused;for(const id of ['click','fun-toggle','restart'])$(id).disabled=paused;if(paused){stopArcade();$('golden-lemon').hidden=true;}last=performance.now();}
async function api(path,{method='GET',body,keepalive=false}={}){const headers={};if(body)headers['Content-Type']='application/json';if(player)headers['X-Player-Id']=player.id;const response=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers,body:body?JSON.stringify(body):undefined,keepalive});let result;try{result=await response.json();}catch{throw new Error('Could not reach cloud saves. Please try again.');}if(!response.ok){const error=new Error(result.error||'Cloud saves are unavailable.');error.status=response.status;throw error;}return result;}
function showConflict(message){clearTimeout(cloudTimer);cloudTimer=0;pauseGame(true);status('Paused · cloud progress changed elsewhere');$('sync-help').textContent=message||'Another tab is playing your empire. Resume here to load the latest cloud save. Unsynced changes in this tab will be replaced.';if(!$('sync-dialog').open)$('sync-dialog').showModal();}
function authUI(){ $('account-toggle').textContent=player?player.username:'Sign in';$('auth-content').hidden=!!player;$('account-profile').hidden=!player;$('account-title').textContent=player?'Your lemonade account':signupMode?'Start your cloud empire':'Welcome back';$('auth-submit').textContent=signupMode?'Create account':'Log in';$('auth-switch').textContent=signupMode?'Already have an account? Log in':'New here? Create an account';$('password').autocomplete=signupMode?'new-password':'current-password';$('account-help').textContent=signupMode?'Pick a username and password. Your current guest progress becomes your first cloud save.':'Log in to keep your lemonade empire across tabs and devices.';if(player)$('profile-name').textContent=`Signed in as ${player.username}. Your progress follows this account.`;}
function writeCloudMeta(){if(!player)return;try{localStorage.setItem(`lemonade-cloud-meta-${player.id}`,JSON.stringify({revision,dirty}));}catch{}}
function pendingLocalSave(result){if(!player)return null;try{const meta=JSON.parse(localStorage.getItem(`lemonade-cloud-meta-${player.id}`)||'null');const cached=JSON.parse(localStorage.getItem(`lemonade-account-${player.id}`)||'null');return meta?.dirty&&meta.revision===result.revision&&cached?.v===1&&cached.savedAt>(result.save?.savedAt||0)?cached:null;}catch{return null;}}
function scheduleCloud(snapshot){if(!player||window.cloudPaused)return;dirty=true;writeCloudMeta();if(!cloudTimer)cloudTimer=setTimeout(()=>{cloudTimer=0;flushCloud().catch(()=>{});},2500);}
window.accountSaveHook=scheduleCloud;
async function flushCloud({force=false,keepalive=false}={}){
  if(inFlight)await inFlight;
  if(!player||!dirty||(!force&&window.cloudPaused))return;
  clearTimeout(cloudTimer);cloudTimer=0;
  const currentEpoch=epoch,save=gameSnapshot();dirty=false;status('Saving your empire…');
  const operation=api('/api/save',{method:'PUT',body:{save,revision,clientId},keepalive}).then(result=>{if(currentEpoch!==epoch)return;revision=result.revision;writeCloudMeta();status('Cloud saved · '+player.username);}).catch(error=>{if(currentEpoch!==epoch)return;if(error.status===409){showConflict(error.message+' Load the latest save to continue. Unsynced changes in this tab will be replaced.');}else if(error.status===401){pauseGame(true);status('Please log in again to continue your cloud empire.');$('profile-error').textContent=error.message;player=null;authUI();if(!$('account-dialog').open)$('account-dialog').showModal();}else{dirty=true;writeCloudMeta();status('Cloud save pending · saved locally');$('profile-error').textContent=error.message;}throw error;}).finally(()=>{if(inFlight===operation)inFlight=null;});inFlight=operation;await operation;
}
async function prepareHandoff(){if(!accountChannel||!player)return;await new Promise(resolve=>{ackResolver=resolve;accountChannel.postMessage({type:'prepare',playerId:player.id,clientId});setTimeout(()=>{if(ackResolver===resolve){ackResolver=null;resolve();}},700);});}
async function takeControl({handoff=true}={}){
  pauseGame(true);status('Loading your cloud empire…');if(handoff)await prepareHandoff();
  const result=await api('/api/play',{method:'POST',body:{clientId}});
  const pending=pendingLocalSave(result);epoch++;dirty=false;clearTimeout(cloudTimer);cloudTimer=0;revision=result.revision;
  if(pending)applySnapshot(pending,true);else if(result.save)applySnapshot(result.save,true);else{reset();}
  SAVE_KEY=`lemonade-account-${player.id}`;
  pauseGame(false);saveGame();status('Cloud saved · '+player.username);authUI();
  accountChannel?.postMessage({type:'claimed',playerId:player.id,clientId});
}
accountChannel?.addEventListener('message',async event=>{const message=event.data;if(!message||message.clientId===clientId)return;if(message.type==='auth-change'){if((player?.id||null)!==message.playerId){pauseGame(true);status('The signed-in account changed in another tab.');$('sync-help').textContent='A different account was signed in or logged out in another tab. Reload this page to use the current account.';$('resume-cloud').textContent='Reload this tab';$('resume-cloud').dataset.reload='true';if(!$('sync-dialog').open)$('sync-dialog').showModal();}return;}if(!player||message.playerId!==player.id)return;if(message.type==='prepare'){pauseGame(true);try{await flushCloud({force:true});}catch{}accountChannel.postMessage({type:'ready',playerId:player.id,clientId,to:message.clientId});showConflict();}else if(message.type==='ready'&&message.to===clientId&&ackResolver){const resolve=ackResolver;ackResolver=null;resolve();}else if(message.type==='claimed'){showConflict();}});
$('account-toggle').addEventListener('click',()=>{authUI();$('account-dialog').showModal();});$('account-close').addEventListener('click',()=>{if(authBusy)return;$('account-dialog').close();});$('account-dialog').addEventListener('cancel',event=>{if(authBusy)event.preventDefault();});$('auth-switch').addEventListener('click',()=>{signupMode=!signupMode;$('auth-error').textContent='';authUI();});
$('account-form').addEventListener('submit',async event=>{event.preventDefault();if(authBusy)return;authBusy=true;$('auth-submit').disabled=true;$('auth-switch').disabled=true;$('auth-error').textContent='';pauseGame(true);try{const body={username:$('username').value,password:$('password').value};if(signupMode)body.save=gameSnapshot();const result=await api(signupMode?'/api/signup':'/api/login',{method:'POST',body});player=result.user;$('password').value='';SAVE_KEY=`lemonade-account-${player.id}`;await takeControl();accountChannel?.postMessage({type:'auth-change',playerId:player.id,clientId});$('account-dialog').close();notify(`Welcome, ${player.username}! Your empire is cloud saved.`);}catch(error){$('auth-error').textContent=error.message;if(!player){pauseGame(false);status('Guest · progress saved on this device');}else{authUI();$('profile-error').textContent='Signed in, but your cloud save could not load. Use Load cloud save to retry.';status('Paused · cloud save could not load');}}finally{authBusy=false;$('auth-submit').disabled=false;$('auth-switch').disabled=false;}});
$('save-now').addEventListener('click',async()=>{$('profile-error').textContent='';try{if(window.cloudPaused){await takeControl();}else{saveGame();await flushCloud();}}catch(error){$('profile-error').textContent=error.message;}});
$('logout').addEventListener('click',async()=>{if(authBusy)return;authBusy=true;$('logout').disabled=true;try{if(!window.cloudPaused){saveGame();await flushCloud();}await api('/api/logout',{method:'POST',body:{}});epoch++;player=null;dirty=false;clearTimeout(cloudTimer);cloudTimer=0;let guest=null;try{guest=localStorage.getItem(GUEST_KEY);}catch{}reset();SAVE_KEY=GUEST_KEY;if(guest)applySnapshot(JSON.parse(guest));pauseGame(false);status('Guest · progress saved on this device');authUI();accountChannel?.postMessage({type:'auth-change',playerId:null,clientId});$('account-dialog').close();notify('Logged out. Your cloud empire is safe.');}catch(error){$('profile-error').textContent=error.message;}finally{authBusy=false;$('logout').disabled=false;}});
$('resume-cloud').addEventListener('click',async()=>{if($('resume-cloud').dataset.reload){location.reload();return;}$('resume-cloud').disabled=true;$('sync-error').textContent='';try{await takeControl();$('sync-dialog').close();}catch(error){$('sync-error').textContent=error.message;}finally{$('resume-cloud').disabled=false;}});$('sync-dialog').addEventListener('cancel',event=>event.preventDefault());
window.addEventListener('pagehide',()=>{if(player&&!window.cloudPaused){dirty=true;flushCloud({keepalive:true}).catch(()=>{});}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&player&&!window.cloudPaused){dirty=true;flushCloud({keepalive:true}).catch(()=>{});}});
window.addEventListener('online',()=>{if(player&&!window.cloudPaused)flushCloud().catch(()=>{});});
(async()=>{try{const result=await api('/api/account');player=result.user;if(player){SAVE_KEY=`lemonade-account-${player.id}`;await takeControl();}else{pauseGame(false);status('Guest · sign in for cloud saves');}}catch(error){if(player){pauseGame(true);status('Cloud save unavailable · retry from your account');$('profile-error').textContent=error.message;}else{pauseGame(false);status('Guest · progress saved on this device');}}finally{window.cloudReady=true;authUI();}})();
